{
  "findings": [
    {
      "ref": "[R31]",
      "area": "age_gating",
      "claim": "A parent reports the app is labeled for ages 3-8 but a 10-year-old child uses it and finds it appropriate.",
      "stance": "neutral",
      "quote": "I’m a almost ten year old girl righting this review and this app is for my almost six year old little brother and when I signed him in I HAD TOO play at least 3 tiny little game and honestly I loved it it goes 3yrs too 8+ years"
    },
    {
      "ref": "[R23]",
      "area": "age_gating",
      "claim": "A parent reports the app is labeled 8+ but a 7-year-old finds it too childish and limited to second grade.",
      "stance": "risk",
      "quote": "It says 8+ and it only goes up to 2nd grade and this is a bit childish for a 7 year old because it was giving like easy things"
    },
    {
      "ref": "[R52]",
      "area": "content",
      "claim": "A parent reports disturbing Halloween-themed content appeared unexpectedly in the app.",
      "stance": "risk",
      "quote": "A grid of scary devil faces and men tied up with their mouth taped shut popped up for about 15 seconds while my kid was working on math. Very disturbing and disappointing since this is such a widely advertised app for homeschooling"
    },
    {
      "ref": "[R26]",
      "area": "content",
      "claim": "A parent reports the app includes yoga routines that conflict with their Catholic beliefs.",
      "stance": "risk",
      "quote": "Instead of just standard kids' games or exercises, the app features and pushes yoga routines. Yoga carries specific spiritual intentions that conflict entirely with our Catholic beliefs, and I do not want this introduced to my daughter. App developers need to be transparent when blending spiritual practices into children's entertainment. Uninstalled immediately."
    },
    {
      "ref": "[R32]",
      "area": "parental_control",
      "claim": "A parent reports insufficient parental controls to remove or disable specific content.",
      "stance": "mitigation",
      "quote": "Parents should be able to remove or disable certain videos and other contents for kits to see."
    },
    {
      "ref": "[R44]",
      "area": "parental_control",
      "claim": "A parent reports the app lacks a timer feature to block non-learning content and limit screen time.",
      "stance": "mitigation",
      "quote": "It needs a timer feature to block out non learning content. I was getting so frustrated using this with my daughter because instead of sticking to the learning paths she’d go to the bug area, or the change clothes features."
    },
    {
      "ref": "[R45]",
      "area": "money",
      "claim": "A parent states the app is actually free and does not require payment.",
      "stance": "neutral",
      "quote": "ACTUALLY FREE YOU DONT NEED TO PAY Thank goodness I use khan academy for school work so when I found out they had a learning games for kids I was so happy and I thought “ they teach fee videos on YouTube “ and it absolutely was free glad to know someone cares for our youth"
    },
    {
      "ref": "[R55]",
      "area": "age_gating",
      "claim": "A parent reports the app's age limit (pre-K to 2nd grade) is insufficient for a 10-year-old child.",
      "stance": "risk",
      "quote": "Up to 2nd grade?! I am  10 years old and the app literally lets you choose your grade from pre-k to 2nd grade. Where is 5th grade?! You need to change this “age thing” immediately or I will delete the app."
    },
    {
      "ref": "[R57]",
      "area": "age_gating",
      "claim": "A parent reports the app's age range is too small for older children who enjoy it.",
      "stance": "risk",
      "quote": "So the game is really fun but the age range is to small I like it and I’m 11 so the highest it goes is 2nd grade even though older kids like it too. Just try to put the age range a little higher like maybe up to middle school, thats all I’m asking."
    },
    {
      "ref": "[R73]",
      "area": "content",
      "claim": "A parent reports the app is 'very, very bad' and advises others not to buy it.",
      "stance": "risk",
      "quote": "Very, very bad Terrible I hate this app!! do not buy this. It is so bad."
    },
    {
      "ref": "[R75]",
      "area": "money",
      "claim": "A parent states the app is completely free with no ads or subscriptions.",
      "stance": "neutral",
      "quote": "This is our kids go to App- so many activities and endless fun! We appreciate that its layout and activities are very well structured for kids- plus everything is included at no cost!"
    },
    {
      "ref": "[R76]",
      "area": "money",
      "claim": "A parent reports the app is free and expresses relief about no subscription costs.",
      "stance": "neutral",
      "quote": "I’m amazed this app is free. My toddler really likes it and I feel good about her being in front of the screen because she’s learning, drawing and coloring things in."
    },
    {
      "ref": "[R79]",
      "area": "money",
      "claim": "A parent states the app is free, has no ads, and gives a 5-star recommendation.",
      "stance": "neutral",
      "quote": "This is a very great game, and I recommend it 💯 percent! Coasts no money! Free from adds! GET THIS GAME NOW! You will be sorry if you don’t get this game right now!!! Khan academy kids download now for free on App Store! 📱5 STARS!"
    },
    {
      "ref": "[R42]",
      "area": "age_gating",
      "claim": "A parent reports the app only goes up to second grade, which is insufficient for a third grader.",
      "stance": "risk",
      "quote": "Good but limited Good for 5 YEAR OLDS it only goes up to second grade and I am going to third grade so I need something more advanced but it is still a very good kid learning app"
    },
    {
      "ref": "[R28]",
      "area": "age_gating",
      "claim": "A parent reports the app only goes up to second grade, which is insufficient for a fifth grader.",
      "stance": "risk",
      "quote": "Terrible for my kid My kid is a fifth grader and it only went to second grade will be pressed 8+ and it didn’t even go up the grade It only stayed at second grade and down."
    },
    {
      "ref": "[R38]",
      "area": "developer_record",
      "claim": "A parent reports the app changed to Halloween theme against their religious beliefs, indicating potential content concerns.",
      "stance": "risk",
      "quote": "This is suppose to be a kid friendly game. My daughter plays this all the time and now because it is October, you switch it to Halloween and because we are against Halloween with every ounce of our being, we can no longer let her play the game. So not cool!"
    }
  ]
}
